contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    receive() external payable {}
    function run(address _recipient, uint amount) public payable {
        require(address(this).balance >= amount);
        address ownerBefore = c.owner();
        bool isOwner = (msg.sender == ownerBefore);
        uint cBalBefore = address(c).balance;
        uint recipBefore = _recipient.balance;
        bool reverted;
        try c.withdrawAll(_recipient) { reverted = false; } catch { reverted = true; }
        uint cBalAfter = address(c).balance;
        uint recipAfter = _recipient.balance;
        if (isOwner) {
            assert(!reverted && cBalAfter == 0 && recipAfter == recipBefore + cBalBefore);
        } else {
            assert(reverted && cBalAfter == cBalBefore && recipAfter == recipBefore);
        }
    }
}

